#include "diagnostics.h"
#include "ttr_version.h"
#include <Windows.h>
#include <commdlg.h>
#include <sstream>
namespace ttr::host {bool ExportDiagnostics(HWND owner,const ExplorerInfo*i,std::uint64_t record,const std::wstring&state,std::wstring&error)noexcept{wchar_t path[MAX_PATH]=L"TaskbarThumbnailReorder-diagnostics.txt";OPENFILENAMEW ofn{sizeof(ofn)};ofn.hwndOwner=owner;ofn.lpstrFilter=L"Text files\0*.txt\0All files\0*.*\0";ofn.lpstrFile=path;ofn.nMaxFile=MAX_PATH;ofn.Flags=OFN_OVERWRITEPROMPT|OFN_PATHMUSTEXIST;ofn.lpstrDefExt=L"txt";if(!GetSaveFileNameW(&ofn))return CommDlgExtendedError()==0;std::wostringstream s;s<<L"Taskbar Thumbnail Reorder "<<TTR_VERSION_W<<L"\r\nState: "<<state<<L"\r\nCompatibility record: "<<record<<L"\r\n";if(i){s<<L"Explorer PID: "<<i->processId<<L"\r\nExplorer path: "<<i->path<<L"\r\n";for(auto&m:i->modules){wchar_t name[40]{};MultiByteToWideChar(CP_UTF8,0,m.identity.baseName,-1,name,40);s<<L"Module: "<<name<<L" timestamp="<<m.identity.timeDateStamp<<L" size="<<m.identity.sizeOfImage<<L" PDB="<<GuidString(m.identity.pdbGuid)<<L" age="<<m.identity.pdbAge<<L"\r\n";}}auto text=s.str();HANDLE f=CreateFileW(path,GENERIC_WRITE,0,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(f==INVALID_HANDLE_VALUE){error=L"Unable to create the diagnostics file.";return false;}const BYTE bom[]={0xEF,0xBB,0xBF};DWORD n{};WriteFile(f,bom,sizeof(bom),&n,nullptr);int bytes=WideCharToMultiByte(CP_UTF8,0,text.data(),static_cast<int>(text.size()),nullptr,0,nullptr,nullptr);std::string utf8(bytes,'\0');WideCharToMultiByte(CP_UTF8,0,text.data(),static_cast<int>(text.size()),utf8.data(),bytes,nullptr,nullptr);bool ok=WriteFile(f,utf8.data(),static_cast<DWORD>(utf8.size()),&n,nullptr)!=FALSE;CloseHandle(f);return ok;} }
